# Let me look for connected components of 0s (not 9, which is background)
from collections import deque

def find_connected_components(grid, value, is_background=lambda v: v == 9):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] == value:
                if is_background(value):
                    continue
                component = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == value:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                if component:
                    components.append(component)
    return components

# Find connected components of 1s
ones_components = find_connected_components(grid, 1, lambda v: v == 9)
print(f"Number of 1-components: {len(ones_components)}")
for i, comp in enumerate(ones_components):
    print(f"Component {i}: {comp}")

# Find connected components of 0s
