    ("rotate90", rotate_90(ones_sig)),
    ("rotate180", rotate_180(ones_sig)),
    ("rotate270", rotate_270(ones_sig)),
    ("flipH", flip_horizontal(ones_sig)),
    ("flipV", flip_vertical(ones_sig)),
]

print("\nTransforms of 1s shape:")
for name, t in transforms:
